/* ===== Cloudflare Orange — 100 native facets (data-spectrum="cloudflare"). Token-driven, self-contained. ===== */
.cloudflare-root{--cloudflare-radius:6px;--cloudflare-font:Inter, "Segoe UI", system-ui, -apple-system, sans-serif;font-family:var(--cloudflare-font,inherit)}
@keyframes cloudflareBtnPulse{0%,100%{box-shadow:0 0 0 0 rgba(var(--_rgb),.5)}50%{box-shadow:0 0 0 6px rgba(var(--_rgb),0)}}
.cloudflare-btn{display:inline-flex;align-items:center;gap:8px;padding:9px 18px;border-radius:var(--cloudflare-radius,999px);background:var(--_c);color:#fff;font-weight:700;border:0;animation:cloudflareBtnPulse 2.4s ease-in-out infinite}
@keyframes cloudflareTgKnob{0%,100%{left:2px}50%{left:20px}}
.cloudflare-toggle{position:relative;width:44px;height:24px;border-radius:999px;background:rgba(var(--_rgb),.28);border:1px solid rgba(var(--_rgb),.5)}
.cloudflare-toggle::after{content:"";position:absolute;top:2px;left:2px;width:18px;height:18px;border-radius:50%;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.7);animation:cloudflareTgKnob 2.6s ease-in-out infinite}
@keyframes cloudflareChipShine{0%{background-position:-160% 0}60%,100%{background-position:260% 0}}
.cloudflare-chip{position:relative;overflow:hidden;display:inline-flex;align-items:center;padding:4px 12px;border-radius:999px;background:rgba(var(--_rgb),.16);border:1px solid rgba(var(--_rgb),.4);color:var(--_c);font-size:12px;font-weight:700}
.cloudflare-chip::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 40%,rgba(var(--_rgb),.4) 50%,transparent 60%);background-size:250% 100%;animation:cloudflareChipShine 3s linear infinite;pointer-events:none}
@keyframes cloudflareMenuSel{0%,100%{background:rgba(var(--_rgb),.12)}50%{background:rgba(var(--_rgb),.26)}}
.cloudflare-menu{min-width:150px;padding:6px;border-radius:var(--cloudflare-radius,12px);background:var(--panel2);border:1px solid var(--line)}
.cloudflare-menu .cloudflare-mi{padding:7px 10px;border-radius:8px;color:var(--ink);font-size:12px}
.cloudflare-menu .cloudflare-sel{color:var(--_c);animation:cloudflareMenuSel 2.8s ease-in-out infinite}
@keyframes cloudflareNotifIn{0%,100%{transform:translateX(-6px);opacity:.75}50%{transform:translateX(0);opacity:1}}
.cloudflare-toast{display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:10px;background:var(--panel2);border:1px solid var(--line);border-left:3px solid var(--_c);color:var(--ink);font-size:12px;animation:cloudflareNotifIn 3s ease-in-out infinite}
.cloudflare-toast::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.8)}
@keyframes cloudflareCalloutEdge{0%{transform:translateX(-120%)}100%{transform:translateX(120%)}}
.cloudflare-callout{position:relative;overflow:hidden;padding:10px 14px;border-radius:10px;background:rgba(var(--_rgb),.1);border:1px solid rgba(var(--_rgb),.35);color:var(--ink);font-size:12px}
.cloudflare-callout::after{content:"";position:absolute;top:0;left:0;height:2px;width:60%;background:linear-gradient(90deg,transparent,var(--_c),transparent);animation:cloudflareCalloutEdge 2.6s linear infinite;pointer-events:none}
@keyframes cloudflareBarGrow{0%{transform:scaleY(.25)}50%{transform:scaleY(1)}100%{transform:scaleY(.25)}}
.cloudflare-chart{display:flex;align-items:flex-end;gap:5px;height:44px;padding:6px 8px;border-radius:10px;background:var(--panel2);border:1px solid var(--line)}
.cloudflare-chart i{flex:1;background:var(--_c);border-radius:3px 3px 0 0;transform-origin:bottom;animation:cloudflareBarGrow 2.4s ease-in-out infinite}
.cloudflare-chart i:nth-child(2){animation-delay:.2s}.cloudflare-chart i:nth-child(3){animation-delay:.4s}.cloudflare-chart i:nth-child(4){animation-delay:.6s}
@keyframes cloudflareInputCaret{0%,49%{opacity:1}50%,100%{opacity:0}}
.cloudflare-field{display:inline-flex;align-items:center;gap:2px;min-width:150px;padding:8px 11px;border-radius:10px;background:var(--panel);border:1px solid var(--_c);box-shadow:0 0 0 3px rgba(var(--_rgb),.18);color:var(--ink);font-size:12px}
.cloudflare-field .cloudflare-caret{width:1.5px;height:14px;background:var(--_c);animation:cloudflareInputCaret 1.1s step-end infinite}
@keyframes cloudflareProg{0%{width:8%}80%,100%{width:96%}}
.cloudflare-prog{width:150px;height:8px;border-radius:999px;background:rgba(var(--_rgb),.18);overflow:hidden}
.cloudflare-prog i{display:block;height:100%;border-radius:inherit;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.6);animation:cloudflareProg 3s ease-in-out infinite}
@keyframes cloudflareAvRing{to{transform:rotate(1turn)}}
.cloudflare-avatar{position:relative;width:46px;height:46px;border-radius:50%;display:grid;place-items:center;background:var(--panel2);color:var(--ink);font-weight:800}
.cloudflare-avatar::before{content:"";position:absolute;inset:-3px;border-radius:50%;background:conic-gradient(from 0deg,var(--_c),transparent 55%,var(--_c));-webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 3px),#000 calc(100% - 3px));mask:radial-gradient(farthest-side,transparent calc(100% - 3px),#000 calc(100% - 3px));animation:cloudflareAvRing 3.4s linear infinite}
@keyframes cloudflareBadgePop{0%,100%{transform:scale(1)}30%{transform:scale(1.25)}}
.cloudflare-badge{display:inline-grid;place-items:center;min-width:22px;height:22px;padding:0 6px;border-radius:999px;background:var(--_c);color:#fff;font-size:11px;font-weight:800;animation:cloudflareBadgePop 2s ease-in-out infinite}
@keyframes cloudflareTabSlide{0%,100%{left:2px}50%{left:calc(50% + 1px)}}
.cloudflare-tabs{position:relative;display:inline-flex;padding:3px;border-radius:999px;background:var(--panel2);border:1px solid var(--line)}
.cloudflare-tabs span{position:relative;z-index:1;padding:5px 14px;font-size:12px;color:var(--ink)}
.cloudflare-tabs::before{content:"";position:absolute;top:3px;bottom:3px;width:calc(50% - 3px);left:2px;border-radius:999px;background:rgba(var(--_rgb),.9);animation:cloudflareTabSlide 3.2s ease-in-out infinite}
@keyframes cloudflareTipFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
.cloudflare-tip{display:inline-block;padding:6px 10px;border-radius:8px;background:var(--panel2);border:1px solid var(--_c);color:var(--ink);font-size:11px;box-shadow:0 4px 14px rgba(var(--_rgb),.3);animation:cloudflareTipFloat 2.6s ease-in-out infinite}
@keyframes cloudflareSpin{to{transform:rotate(1turn)}}
.cloudflare-spinner{width:26px;height:26px;border-radius:50%;border:3px solid rgba(var(--_rgb),.22);border-top-color:var(--_c);animation:cloudflareSpin 1s linear infinite}
@keyframes cloudflareCardGlow{0%,100%{box-shadow:0 0 0 1px var(--line)}50%{box-shadow:0 0 16px rgba(var(--_rgb),.4)}}
.cloudflare-card{width:150px;padding:12px;border-radius:var(--cloudflare-radius,12px);background:var(--card);color:var(--ink);animation:cloudflareCardGlow 3.4s ease-in-out infinite}
.cloudflare-card b{color:var(--_c);font-size:12px}.cloudflare-card p{margin:4px 0 0;font-size:11px;color:var(--muted)}
@keyframes cloudflareCheckIn{0%,20%{clip-path:inset(0 100% 0 0)}60%,100%{clip-path:inset(0 0 0 0)}}
.cloudflare-check{position:relative;width:22px;height:22px;border-radius:6px;background:var(--_c);display:grid;place-items:center}
.cloudflare-check::after{content:"✓";color:#fff;font-size:14px;font-weight:900;animation:cloudflareCheckIn 2.4s ease-in-out infinite}
@keyframes cloudflareSliderThumb{0%,100%{left:2px}50%{left:calc(100% - 16px)}}
.cloudflare-slider{position:relative;width:150px;height:6px;border-radius:999px;background:rgba(var(--_rgb),.2)}
.cloudflare-slider::before{content:"";position:absolute;top:-5px;left:2px;width:16px;height:16px;border-radius:50%;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.6);animation:cloudflareSliderThumb 3s ease-in-out infinite}
@media(prefers-reduced-motion:reduce){.cloudflare-root [class*="cloudflare-"],.cloudflare-root [class*="cloudflare-"]::before,.cloudflare-root [class*="cloudflare-"]::after,.cloudflare-root [class],.cloudflare-root [class]::before,.cloudflare-root [class]::after{animation:none!important}}

